"""A prompt to delegate, identified by a client-generated task id."""

from __future__ import annotations

from dataclasses import dataclass
from typing import ClassVar, Self

from orbital.bridges.models.utils import (
    is_task_id,
    read_int,
    read_str,
    require_exact_keys,
    require_object,
)


@dataclass(frozen=True, slots=True)
class TaskRequest:
    """A task submission: id, prompt and execution timeout.

    * ``task_id`` is a canonical, lowercase UUID version 4, generated by the client.
    * ``prompt`` is passed to Claude Code unchanged; it must not be blank.
    * ``execution_timeout_seconds`` is the deadline the server enforces (at least 1).
    """

    task_id: str
    prompt: str
    execution_timeout_seconds: int

    KEYS: ClassVar[frozenset[str]] = frozenset({"task_id", "prompt", "execution_timeout_seconds"})

    def __post_init__(self) -> None:
        if not is_task_id(self.task_id):
            raise ValueError("task_id must be a canonical, lowercase UUID version 4")
        if not isinstance(self.prompt, str) or not self.prompt.strip():
            raise ValueError("prompt must be a non-blank string")
        try:
            self.prompt.encode("utf-8")
        except UnicodeEncodeError:
            raise ValueError(
                "prompt must be valid Unicode text (it has a lone surrogate)"
            ) from None
        timeout = self.execution_timeout_seconds
        if isinstance(timeout, bool) or not isinstance(timeout, int) or timeout < 1:
            raise ValueError("execution_timeout_seconds must be an integer of at least 1")

    def to_dict(self) -> dict[str, object]:
        """Return the wire form of the submit request."""
        return {
            "task_id": self.task_id,
            "prompt": self.prompt,
            "execution_timeout_seconds": self.execution_timeout_seconds,
        }

    @classmethod
    def from_dict(cls, value: object) -> Self:
        """Strictly parse the wire form; raise ``ValueError`` if it is invalid."""
        document = require_object(value, "request")
        require_exact_keys(document, cls.KEYS, "request")
        return cls(
            read_str(document, "task_id", "request"),
            read_str(document, "prompt", "request"),
            read_int(document, "execution_timeout_seconds", "request"),
        )
